def hero(k,h,p): return '<section class="container page-hero"><span class="kicker">%s</span><h1>%s</h1><p>%s</p></section>'%(k,h,p)
def sec(k,h,p,inner,cls=""): return '<section class="container %s"><div class="sec-head reveal"><span class="kicker">%s</span><h2>%s</h2>%s</div>%s</section>'%(cls,k,h,("<p>%s</p>"%p) if p else "",inner)
def band(h="Ready to build something great?",p="Tell us about your project and get a free consultation within 24 hours."):
    return '<section class="container"><div class="cta-band reveal"><div><h2>%s</h2><p>%s</p></div><div class="cta"><a class="btn primary" href="/contact/">Start your project</a><a class="btn" style="color:#101827" href="https://wa.me/%s?text=Hi%%20INFLUXYN" target="_blank" rel="noopener">WhatsApp us</a></div></div></section>'%(h,p,TEL)
def svc_cards(): return '<div class="grid g3">'+"".join('<a class="card reveal" href="/services/%s/"><div class="ico">%s</div><h3>%s</h3><p>%s</p><b>Learn more <i class="fa-solid fa-arrow-right" aria-hidden="true"></i></b></a>'%(s["slug"],s["icon"],s["name"],E_(s["short"])) for s in SERVICES)+"</div>"
def proj_cards(items,filt=False):
    return '<div class="grid g2">'+"".join('<article class="card reveal" data-cat="%s"><span class="num">%02d · %s</span><h3>%s</h3><p>%s</p><div class="tags">%s</div><p style="margin:16px 0 0"><a class="btn sm" href="%s" target="_blank" rel="noopener">Visit project <i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></a></p></article>'%(E_(c),i+1,E_(c),E_(n),E_(d),"".join("<span>%s</span>"%t for t in tg),u) for i,(n,c,u,d,tg) in enumerate(items))+"</div>"
def plans():
    o='<div class="toggle" role="group" aria-label="Currency"><button class="on" data-cur="lkr" type="button">Sri Lankan Rs.</button><button data-cur="usd" type="button">US Dollar</button></div><div class="grid g4">'
    for n,t,l,u,y,no,pop in PLANS:
        o+='<div class="card reveal%s">%s<h3>%s</h3><p>%s</p><div class="price"><span data-lkr="%s" data-usd="%s">Rs. %s</span> <small>full site</small></div><ul class="list">%s%s</ul><p style="margin-top:18px"><a class="btn %s" href="/contact/?plan=%s">%s</a></p></div>'%(" pop" if pop else "",'<span class="badge">Most popular</span>' if pop else "",n,t,f"{l:,}",u,f"{l:,}","".join("<li>%s</li>"%i for i in y),"".join('<li class="no">%s</li>'%i for i in no),"primary" if pop else "",n.lower(),"Contact sales" if n=="Enterprise" else "Get started")
    return o+"</div>"
def demos_html(): return '<div class="grid g2">'+"".join('<article class="card reveal"><div class="ico">%s</div><h3>%s</h3><p>%s</p><p style="margin:0"><a class="btn sm primary" href="%s" target="_blank" rel="noopener">View live project <i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></a> <a class="btn sm" href="/contact/?demo=%s">Request demo</a></p></article>'%(i,n,E_(d),u,n.replace(" ","+")) for n,i,u,d in DEMOS)+"</div>"
def testi(): return '<div class="grid g3">'+"".join('<figure class="card quote reveal" style="margin:0"><div class="stars" aria-label="5 out of 5 stars"><span class="fa-stack-stars" aria-hidden="true"><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i></span></div><blockquote style="margin:10px 0 0">“%s”<cite>%s · %s</cite></blockquote></figure>'%(E_(q),n,r) for q,n,r in TESTI)+"</div>"
def process(): return '<div class="grid g4">'+"".join('<div class="card reveal"><span class="num">STEP 0%d</span><h3>%s</h3><p>%s</p></div>'%(i+1,n,d) for i,(n,d) in enumerate(PROCESS))+"</div>"
